package app.daemon.deck;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.media.*;import org.json.*;
public class Alarms {
 static final String CHANNEL="mission_notifications_v3",RINGING="mission_ringing_v3";
 static PendingIntent pending(Context c,JSONObject a)throws Exception{return PendingIntent.getBroadcast(c,0,new Intent(c,AlarmReceiver.class).setData(Uri.parse("daemon://alarm/"+Uri.encode(a.getString("id")))).putExtra("title",a.getString("title")).putExtra("body",a.getString("body")).putExtra("type",a.optString("type","notification")).putExtra("sound",a.optString("sound","")).putExtra("volumeDismiss",a.optBoolean("volumeDismiss",true)),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static synchronized String set(Context c,String json){try{JSONArray next=new JSONArray(json);if(next.length()>60000)throw new Exception("Too many reminders");AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);JSONArray old=new JSONArray(c.getSharedPreferences("alarms",0).getString("plan","[]"));for(int i=0;i<old.length();i++)am.cancel(pending(c,old.getJSONObject(i)));c.getSharedPreferences("alarms",0).edit().putString("plan",json).commit();if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())return "Exact scheduling access required.";for(int i=0;i<next.length();i++){JSONObject a=next.getJSONObject(i);long at=a.getLong("at");if(at>System.currentTimeMillis())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending(c,a));}return "";}catch(Exception e){return "Reminder scheduling failed: "+e.getMessage();}}
 public static void restore(Context c){set(c,c.getSharedPreferences("alarms",0).getString("plan","[]"));}
 public static void channel(Context c){notificationChannel(c,"");NotificationChannel ring=new NotificationChannel(RINGING,"Ringing alarms",NotificationManager.IMPORTANCE_HIGH);ring.setSound(null,null);ring.enableVibration(true);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ring);}
 static String notificationChannel(Context c,String sound){if(!sound.isEmpty())try{android.content.res.AssetFileDescriptor f=c.getContentResolver().openAssetFileDescriptor(Uri.parse(sound),"r");if(f==null)sound="";else f.close();}catch(Exception e){sound="";}String id=sound.isEmpty()?CHANNEL:CHANNEL+"_"+Integer.toHexString(sound.hashCode());NotificationChannel ch=new NotificationChannel(id,"Mission notifications",NotificationManager.IMPORTANCE_HIGH);ch.enableVibration(true);Uri uri=sound.isEmpty()?RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION):Uri.parse(sound);ch.setSound(uri,new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION).build());((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(ch);return id;}
 static Notification notification(Context c,Intent i,boolean alarm){channel(c);Intent open=new Intent(c,alarm?AlarmActivity.class:MainActivity.class).putExtras(i).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent content=PendingIntent.getActivity(c,alarm?1:0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder n=new Notification.Builder(c,alarm?RINGING:notificationChannel(c,i.getStringExtra("sound")==null?"":i.getStringExtra("sound"))).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(i.getStringExtra("title")).setContentText(i.getStringExtra("body")).setStyle(new Notification.BigTextStyle().bigText(i.getStringExtra("body"))).setCategory(alarm?Notification.CATEGORY_ALARM:Notification.CATEGORY_REMINDER).setContentIntent(content).setAutoCancel(!alarm);if(alarm){PendingIntent stop=PendingIntent.getBroadcast(c,2,new Intent(c,AlarmReceiver.class).setAction("dismiss"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);n.setOngoing(true).setFullScreenIntent(content,true).addAction(new Notification.Action.Builder(null,"Dismiss",stop).build());}return n.build();}
}
